---
 assets/dev/js/frontend/utils/video-api/base-loader.js | 6 +++---
 1 file changed, 3 insertions(+), 3 deletions(-)

diff --git a/assets/dev/js/frontend/utils/video-api/base-loader.js b/assets/dev/js/frontend/utils/video-api/base-loader.js
index bba8915409e5..8ae075faef70 100644
--- a/assets/dev/js/frontend/utils/video-api/base-loader.js
+++ b/assets/dev/js/frontend/utils/video-api/base-loader.js
@@ -17,10 +17,10 @@ export default class BaseLoader extends elementorModules.ViewModule {
 	insertAPI() {
 		// Check if consent is given for the external video service (if no `consentApi` is available, fallback to immediate loading)
 		const apiUrl = this.getApiURL();
-		const consentPromise = (window.consentApi && window.consentApi.unblock(apiUrl) || Promise.resolve());
-		consentPromise.then(() => {
+		const consentPromise = window.consentApi ? window.consentApi.unblock( apiUrl ) : Promise.resolve();
+		consentPromise.then( () => {
 			this.elements.$firstScript.before( jQuery( '<script>', { src: apiUrl } ) );
-		});
+		} );

 		this.setSettings( 'isInserted', true );
 	}
